w("")
w("| cell | A | B | rules | games | A wins | 95% CI | sets A−B per game | 95% CI | decl. acc. A / B | ask hit A / B |")
w("|---|---|---|---|---:|---:|---|---:|---|---|---|")
names = {"default": "FishLab default (declare at any time, cardless may declare)", "nooot": "`--no-out-of-turn` (KRAKEN's dialect: declare on turn only)",
         "nooot_nocardless": "`--no-out-of-turn --no-cardless-declare`", "legacy": "`--legacy`", "mirror_kraken": "default (mirror control)",
         "kv6_vs_v07": "default", "kraken_vs_v06": "default", "kraken_vs_fcheap": "default", "kraken_vs_v05": "default", "kraken_vs_v04": "default"}
short = {"kraken": "KRAKEN", "kv6": "KV FishBot v0.6", "v06": "FishBot v0.6", "v05": "FishBot v0.5", "v04": "FishBot v0.4"}
def nm(s):
    if s.startswith("v07:"): return "SESTINA v1.0"
    if s.startswith("v06:s1=1"): return "F-cheap (v0.6 + search)"
